import{_ as s,o as a,c as e,a4 as l}from"./chunks/framework.DzJZdBQK.js";const c=JSON.parse('{"title":"如何基于Docker快速实现持续交付系统-环境搭建","description":"","frontmatter":{"date":"2020-09-07T15:56:24","title":"如何基于Docker快速实现持续交付系统-环境搭建","categories":["教程100","写作"],"tags":["教程100","写作"]},"headers":[{"level":2,"title":"目的","slug":"目的","link":"#目的","children":[]},{"level":2,"title":"软件简单介绍","slug":"软件简单介绍","link":"#软件简单介绍","children":[{"level":3,"title":"Docker","slug":"docker","link":"#docker","children":[]},{"level":3,"title":"Portainer","slug":"portainer","link":"#portainer","children":[]},{"level":3,"title":"Gitlab","slug":"gitlab","link":"#gitlab","children":[]},{"level":3,"title":"Jenkins","slug":"jenkins","link":"#jenkins","children":[]},{"level":3,"title":"Ansible","slug":"ansible","link":"#ansible","children":[]}]},{"level":2,"title":"安装Docker","slug":"安装docker","link":"#安装docker","children":[]},{"level":2,"title":"安装Portainer","slug":"安装portainer","link":"#安装portainer","children":[]},{"level":2,"title":"安装Gitlab CE","slug":"安装gitlab-ce","link":"#安装gitlab-ce","children":[]},{"level":2,"title":"安装Jenkins","slug":"安装jenkins","link":"#安装jenkins","children":[]},{"level":2,"title":"安装Ansible","slug":"安装ansible","link":"#安装ansible","children":[]},{"level":2,"title":"未完待续","slug":"未完待续","link":"#未完待续","children":[]},{"level":2,"title":"参考链接","slug":"参考链接","link":"#参考链接","children":[]}],"relativePath":"posts/course100/002.md","filePath":"posts/course100/002.md"}'),t={name:"posts/course100/002.md"};function n(h,i,r,p,k,o){return a(),e("div",null,[...i[0]||(i[0]=[l(`<h2 id="目的" tabindex="-1">目的 <a class="header-anchor" href="#目的" aria-label="Permalink to &quot;目的&quot;">​</a></h2><p>这篇介绍基于Docker快速实现持续交付系统。持续交付主要涉及代码管理，集成打包与自动部署几个环节。我们使用GitLab CE解决代码管理，使用Jenkins解决集成打包，使用Ansible解决自动部署，同时使用Portainer来管理Docker。这次先把需要的环境搭建起来，后续还会继续写一篇关于验证和调整的部分。</p><p>本文使用CentOS 7.8。</p><h2 id="软件简单介绍" tabindex="-1">软件简单介绍 <a class="header-anchor" href="#软件简单介绍" aria-label="Permalink to &quot;软件简单介绍&quot;">​</a></h2><h3 id="docker" tabindex="-1">Docker <a class="header-anchor" href="#docker" aria-label="Permalink to &quot;Docker&quot;">​</a></h3><p>Docker 是一个开源的应用容器引擎，基于 Go 语言 并遵从Apache2.0协议开源。Docker 可以让开发者打包他们的应用以及依赖包到一个轻量级、可移植的容器中，然后发布到任何流行的 Linux 机器上，也可以实现虚拟化。容器是完全使用沙箱机制，比虚拟机更加强大，体积小，运行速度快，Docker 容器可以打包为镜像文件(类似VM虚拟机的那些快照文件)，迁移的时候我们只需要在新服务器上安装Docker,就能把之前打包好的镜像文件导入到 Docker 里面，运行容器，就能实现访问，不需要重新配置环境。</p><h3 id="portainer" tabindex="-1">Portainer <a class="header-anchor" href="#portainer" aria-label="Permalink to &quot;Portainer&quot;">​</a></h3><p><code>Portainer</code>是<code>Docker</code>的图形化管理工具，提供状态显示面板、应用模板快速部署、容器镜像网络数据卷的基本操作（包括上传下载镜像，创建容器等操作）、事件日志显示、容器控制台操作、<code>Swarm</code>集群和服务等集中管理和操作、登录用户管理和控制等功能。功能十分全面，基本能满足中小型单位对容器管理的全部需求。</p><h3 id="gitlab" tabindex="-1">Gitlab <a class="header-anchor" href="#gitlab" aria-label="Permalink to &quot;Gitlab&quot;">​</a></h3><p>GitLab 是一个用于仓库管理系统的开源项目，使用 Git 作为代码管理工具，并在此基础上搭建起来的web服务。<strong>GitLab</strong>是由 GitLabInc. 开发，使用 MIT 许可证的基于网络的 Git 仓库管理工具，且具有 wiki 和 issue 跟踪功能。使用 Git 作为代码管理工具，并在此基础上搭建起来的 web 服务。</p><h3 id="jenkins" tabindex="-1">Jenkins <a class="header-anchor" href="#jenkins" aria-label="Permalink to &quot;Jenkins&quot;">​</a></h3><p>Jenkins 是一个开源软件项目，是基于 Java 开发的一种持续集成工具，用于监控持续重复的工作，旨在提供一个开放易用的软件平台，使软件的持续集成变成可能。</p><h3 id="ansible" tabindex="-1">Ansible <a class="header-anchor" href="#ansible" aria-label="Permalink to &quot;Ansible&quot;">​</a></h3><p>ansible 是新出现的自动化运维工具，基于 Python 开发，集合了众多运维工具（puppet、cfengine、chef、func、fabric）的优点，实现了批量系统配置、批量程序部署、批量运行命令等功能。ansible 是基于模块工作的，本身没有批量部署的能力。真正具有批量部署的是ansible 所运行的模块，ansible 只是提供一种框架。</p><h2 id="安装docker" tabindex="-1">安装Docker <a class="header-anchor" href="#安装docker" aria-label="Permalink to &quot;安装Docker&quot;">​</a></h2><ul><li>设置仓库</li></ul><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> yum</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -y</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> yum-utils</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> yum-config-manager</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    --add-repo</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">    https://download.docker.com/linux/centos/docker-ce.repo</span></span></code></pre></div><ul><li>安装Docker Engine</li></ul><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> yum</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docker-ce</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docker-ce-cli</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> containerd.io</span></span></code></pre></div><ul><li>启动Docker</li></ul><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> systemctl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> start</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docker</span></span></code></pre></div><ul><li>开机启动</li></ul><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> systemctl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> enable</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docker</span></span></code></pre></div><ul><li>下载Docker Compose</li></ul><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -L</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;https://github.com/docker/compose/releases/download/1.26.2/docker-compose-$(</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">uname</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -s</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">)-$(</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">uname</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -m</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">)&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -o</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /usr/local/bin/docker-compose</span></span></code></pre></div><ul><li>设置权限</li></ul><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> chmod</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> +x</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /usr/local/bin/docker-compose</span></span></code></pre></div><h2 id="安装portainer" tabindex="-1">安装Portainer <a class="header-anchor" href="#安装portainer" aria-label="Permalink to &quot;安装Portainer&quot;">​</a></h2><ul><li>单机版运行</li></ul><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -d</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -p</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 9000:9000</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    --restart=always</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    -v</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /var/run/docker.sock:/var/run/docker.sock</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    --name</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> prtainer</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">    portainer/portainer</span></span></code></pre></div><ul><li>通过<a href="http://ip:9000" target="_blank" rel="noreferrer">http://ip:9000</a>，进行访问。首次访问需要设置用户名密码(admin/portainer)，并连接本地Docker。</li></ul><h2 id="安装gitlab-ce" tabindex="-1">安装Gitlab CE <a class="header-anchor" href="#安装gitlab-ce" aria-label="Permalink to &quot;安装Gitlab CE&quot;">​</a></h2><ul><li>通过Portainer的GitlabCE的模板创建容器，设置容器名，及高级选项，注意为端口和卷的映射。</li><li>通过<a href="http://xn--ip-3e9fw1jisgwqk" target="_blank" rel="noreferrer">http://ip进行访问</a>，登录时会提示需要输入root用户的密码(gitlabce)。</li></ul><h2 id="安装jenkins" tabindex="-1">安装Jenkins <a class="header-anchor" href="#安装jenkins" aria-label="Permalink to &quot;安装Jenkins&quot;">​</a></h2><ul><li>通过Portainer的GitlabCE的模板创建容器，设置容器名，及高级选项，注意为端口和卷的映射，这里</li><li>连接到容器里，/var/jenkins_home/secrets/initialAdminPassword，取出初始密码。</li><li>安装推荐插件</li><li>创建管理员用户(root/jenkins)</li></ul><h2 id="安装ansible" tabindex="-1">安装Ansible <a class="header-anchor" href="#安装ansible" aria-label="Permalink to &quot;安装Ansible&quot;">​</a></h2><ul><li>更新源</li></ul><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> yum</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -y</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> epel-release</span></span></code></pre></div><ul><li>安装</li></ul><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> yum</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -y</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ansible</span></span></code></pre></div><p>这里暂时没有使用Docker来安装，而是直接安装在宿主机上。这样可以通过Jenkins启动宿主机脚本，从而执行Ansible脚本，创建容器。</p><p>还有一个思路是在Jenkins的Docker中同时安装Ansible，这样Jenkins编写部署脚本会更容易些。后面把流程跑通后进一步尝试。</p><h2 id="未完待续" tabindex="-1">未完待续 <a class="header-anchor" href="#未完待续" aria-label="Permalink to &quot;未完待续&quot;">​</a></h2><p>下一篇会继续介绍，整体持续交付系统的验证过程。</p><h2 id="参考链接" tabindex="-1">参考链接 <a class="header-anchor" href="#参考链接" aria-label="Permalink to &quot;参考链接&quot;">​</a></h2><p>这次其实网上查看了不少文档，但自己时间拖得比较长，不少文章链接可能没记上。</p><p><a href="https://docs.docker.com/engine/install/centos/" target="_blank" rel="noreferrer">Install Docker Engine on CentOS</a></p><p><a href="https://blog.csdn.net/hanzheng260561728/article/details/105138225" target="_blank" rel="noreferrer">https://blog.csdn.net/hanzheng260561728/article/details/105138225</a></p><p><a href="https://blog.csdn.net/A632189007/article/details/78779920" target="_blank" rel="noreferrer">https://blog.csdn.net/A632189007/article/details/78779920</a></p><p><a href="https://www.cnblogs.com/leozhanggg/p/12040338.html" target="_blank" rel="noreferrer">https://www.cnblogs.com/leozhanggg/p/12040338.html</a></p><p><a href="https://www.jianshu.com/p/14e356cf8bb4" target="_blank" rel="noreferrer">https://www.jianshu.com/p/14e356cf8bb4</a></p><p><a href="https://cloud.tencent.com/developer/news/370703" target="_blank" rel="noreferrer">https://cloud.tencent.com/developer/news/370703</a></p><p><a href="https://www.jianshu.com/p/4923348ef3da" target="_blank" rel="noreferrer">https://www.jianshu.com/p/4923348ef3da</a></p><p><a href="https://www.cnblogs.com/bigben0123/p/7886092.html" target="_blank" rel="noreferrer">https://www.cnblogs.com/bigben0123/p/7886092.html</a></p><p><a href="https://www.jianshu.com/p/eb3cbb34be97" target="_blank" rel="noreferrer">https://www.jianshu.com/p/eb3cbb34be97</a></p><p><a href="https://www.jianshu.com/p/080a962c35b6" target="_blank" rel="noreferrer">https://www.jianshu.com/p/080a962c35b6</a></p><p><a href="https://blog.csdn.net/anqixiang/article/details/104968469" target="_blank" rel="noreferrer">https://blog.csdn.net/anqixiang/article/details/104968469</a></p><p><a href="https://www.jianshu.com/p/eeb15a408d88" target="_blank" rel="noreferrer">https://www.jianshu.com/p/eeb15a408d88</a></p><p><a href="https://www.w3cschool.cn/automate_with_ansible/automate_with_ansible-1khc27p1.html" target="_blank" rel="noreferrer">https://www.w3cschool.cn/automate_with_ansible/automate_with_ansible-1khc27p1.html</a></p>`,59)])])}const g=s(t,[["render",n]]);export{c as __pageData,g as default};
